"""
FVE Proof: INV-002 - Bounded key rotation buffers with maximum 1024 active secrets

This proof verifies that:
1. Buffer never exceeds MAX_ACTIVE_KEYS (1024)
2. Expired keys are automatically cleaned up
3. Key rotation respects TTL boundaries
"""

import sys
import asyncio
import time

def prove_invariant_002():
    """Formal verification of INV-002."""
    proofs = []
    
    try:
        from gateway import KeyRotationBuffer, SecureKey, MAX_ACTIVE_KEYS, KEY_ROTATION_TTL
        
        loop = asyncio.new_event_loop()
        
        async def test_buffer_capacity():
            """Proof 1: Buffer never exceeds max capacity."""
            buffer = KeyRotationBuffer(max_size=10)  # Use smaller size for testing
            
            # Try to exceed capacity
            for i in range(15):
                key = SecureKey(
                    key_id=f"key_{i}",
                    public_key=b'\x01' * 1568,
                    ciphertext=b'\x02' * 1568,
                    shared_secret=b'\x03' * 32,
                    created_at=time.monotonic(),
                    expires_at=time.monotonic() + 1000
                )
                await buffer.add_key(key)
            
            assert buffer.active_count <= 10, f"Buffer exceeded capacity: {buffer.active_count}"
            return True
        
        async def test_expired_cleanup():
            """Proof 2: Expired keys are cleaned up."""
            buffer = KeyRotationBuffer(max_size=100)
            
            # Add expired keys
            for i in range(5):
                key = SecureKey(
                    key_id=f"expired_{i}",
                    public_key=b'\x01' * 1568,
                    ciphertext=b'\x02' * 1568,
                    shared_secret=b'\x03' * 32,
                    created_at=0,
                    expires_at=0  # Already expired
                )
                await buffer.add_key(key)
            
            # Run cleanup
            cleaned = await buffer.cleanup_expired()
            assert cleaned == 5, f"Expected 5 cleaned, got {cleaned}"
            assert buffer.active_count == 0, f"Buffer not empty: {buffer.active_count}"
            return True
        
        async def test_key_rotation():
            """Proof 3: Key rotation respects TTL."""
            buffer = KeyRotationBuffer(max_size=100)
            
            key = SecureKey(
                key_id="rotation_test",
                public_key=b'\x01' * 1568,
                ciphertext=b'\x02' * 1568,
                shared_secret=b'\x03' * 32,
                created_at=time.monotonic(),
                expires_at=time.monotonic() + KEY_ROTATION_TTL
            )
            
            # Rotate key
            rotated = key.rotate()
            assert rotated.status.name == "ROTATING", "Rotated key status incorrect"
            assert key.status.name == "EXPIRED", "Original key not marked expired"
            assert rotated.expires_at - rotated.created_at <= KEY_ROTATION_TTL + 0.1, "TTL violation"
            return True
        
        # Run proofs
        proofs.append(("INV-002.1", "Buffer capacity enforcement", loop.run_until_complete(test_buffer_capacity())))
        proofs.append(("INV-002.2", "Expired key cleanup", loop.run_until_complete(test_expired_cleanup())))
        proofs.append(("INV-002.3", "Key rotation TTL", loop.run_until_complete(test_key_rotation())))
        
        loop.close()
        
    except Exception as e:
        proofs.append(("INV-002", f"Proof execution failed: {e}", False))
    
    return proofs

if __name__ == '__main__':
    results = prove_invariant_002()
    for name, desc, passed in results:
        status = "PASS" if passed else "FAIL"
        print(f"[{status}] {name}: {desc}")
    
    if all(p for _, _, p in results):
        print("\nINV-002: ALL PROOFS PASSED")
        sys.exit(0)
    else:
        print("\nINV-002: PROOFS FAILED")
        sys.exit(1)